    pos = -idx - 1;
    if (m->len == m->cap) {
        NvEntry *items = (NvEntry *)nv_alloc(sizeof(NvEntry) * (size_t)m->cap * 2);
        memcpy(items, m->items, sizeof(NvEntry) * (size_t)m->len);
        m->items = items;
        m->cap *= 2;
    }
    memmove(m->items + pos + 1, m->items + pos, sizeof(NvEntry) * (size_t)(m->len - pos));
    m->items[pos].key = key;
    m->items[pos].val = val;
    m->len++;
